function releaseMouse(){if(document.pointerLockElement)document.exitPointerLock?.();}
function lockMouse(){if(touchDevice()||!world?.firstPerson||!running||panel||paused||gamepadActive)return;try{const promise=$('ocean').requestPointerLock?.();promise?.catch?.(()=>toast('點一下畫面啟用滑鼠環視；也可按住右鍵拖曳。'));}catch{toast('可按住滑鼠右鍵拖曳環視。');}}
