let world,running=false,panel=null,paused=false,film=null,destination=null,selectedTarget=null,nearest=null,salvaging=null,buildType=null,buildRot=0,gamepadActive=false,lastInput='keyboard',geneTab='collection',cameraDrag=null,keys=new Set(),joystick={x:0,y:0},modalRestore=null,repelCooldown=0,attackCooldown=0,uiTimer=0,saveTimer=0,spawnTimer=0,discoveryTimer=0,panelTimer=0,frameTime=0,padGridTimer=0,preferParents=['',''],menuFocus=null;
