 if(panel==='journal'){body.innerHTML='<div class="info-strip">'+(state.completed?'主線第一章已完成，仍可自由擴建與培育。':'主線：打撈物資 → 擴建 2 格地基 → 避難所 → 集水器 → 訊號塔。')+'</div>'+state.log.map(l=>`<article class="journal-entry"><small>DAY ${l.day.toString().padStart(2,'0')}</small><h3>${esc(l.title)}</h3><p>${esc(l.text)}</p></article>`).join('');body.insertAdjacentHTML('afterbegin',islandMenu());bindIslandMenu(body);}
