 body.querySelectorAll('[data-gene-tab]').forEach(b=>b.onclick=()=>{geneTab=b.dataset.geneTab;renderPanel();});if(geneTab==='collection'){if(!state.tamed.length){body.innerHTML+='<p>先建造展示池，再帶誘餌靠近生物。間隔 18 秒投餌、約 10–20 次建立信任，牠就會回到這裡。</p><button class="full-button" id="go-build-pen">建造展示池</button>';$('go-build-pen').onclick=()=>openPanel('build');}else{body.innerHTML+=state.tamed.map(p=>{const ph=phenotype(p.genome);return`<article class="creature-card"><div class="specimen-hero"><img class="specimen-image" alt="${esc(p.name)}的 3D 外形" src="${world.thumbnail(p.genome,p.id)}"></div><div class="specimen-meta"><h3>${esc(p.name)}<small>GEN ${p.generation.toString().padStart(2,'0')}</small></h3><div class="gene-chips">${describeGenes(p.genome).map(t=>`<span>${t}</span>`).join('')}</div><div class="mini-stats"><span>游速<b>${ph.speed}</b></span><span>防禦<b>${ph.armor}</b></span><span>親和<b>${ph.affinity}</b></span></div><p>${ABILITIES[ph.ability]} · ${['每 55 秒帶回木材','減少你遭受的生物傷害','每 55 秒生成異晶','每 55 秒帶回金屬'][ph.ability]}<br>基因 ${dnaCode(p.genome)} · ${p.mutations} 處新突變${p.parentNames?'<br>親代：'+p.parentNames.map(esc).join(' × '):'<br>野生始祖'}</p></div></article>`;}).join('');}}
 else{const opts=selected=>state.tamed.map(p=>`<option value="${esc(p.id)}" ${selected===p.id?'selected':''}>${esc(p.name)} · G${p.generation} · ${dnaCode(p.genome).slice(0,4)}</option>`).join('');if(state.tamed.length<2)body.innerHTML+='<p>需要先馴化兩隻不同的個體。跨外形生物也能配對。</p>';else if(!count(state,'hatchery')){body.innerHTML+='<p>兩個親代已就緒。請先在木筏上建造基因孵化台。</p><button class="full-button" id="go-hatchery">建造孵化台</button>';$('go-hatchery').onclick=()=>openPanel('build');}else{if(!state.tamed.some(p=>p.id===preferParents[0]))preferParents[0]=state.tamed[0].id;if(!state.tamed.some(p=>p.id===preferParents[1]))preferParents[1]=state.tamed[1].id;body.innerHTML+=`<section class="breed-box"><h3>讓兩段生命，產生新的可能</h3><label class="field-label" for="parent-a">親代 A</label><select class="gene-select" id="parent-a">${opts(preferParents[0])}</select><label class="field-label" for="parent-b">親代 B</label><select class="gene-select" id="parent-b">${opts(preferParents[1])}</select><button class="primary full-button" id="breed-btn">開始雜交 · 異晶 1 / 口糧 2</button><p>雙親需要羈絆 35。孵育 30 秒。每組基因各繼承一半親代等位基因，每個等位基因有 4.5% 機率發生新突變。後代長成後仍可繼續配對。</p></section>`;$('parent-a').onchange=()=>preferParents[0]=$('parent-a').value;$('parent-b').onchange=()=>preferParents[1]=$('parent-b').value;$('breed-btn').onclick=()=>{const r=breed(state,$('parent-a').value,$('parent-b').value);if(r.ok){toast('基因重組成功。30 秒後迎接新生命。');audio.note(940,.4);save(true);renderPanel();updateUI();}else toast(r.error,true);};}body.innerHTML+='<div id="eggs-list"></div><p class="section-label">重組沒有終點</p><p>16 組雙份基因決定體型、鰭、尾、角、花紋、色彩與能力。256³² 種理論基因編碼，外觀表現會有相似組合；持續雜交與突變可探索大量後代。</p>';renderEggs();}
